package com.resumeanalyzer.service;
import com.resumeanalyzer.dto.*; import com.resumeanalyzer.entity.User; import com.resumeanalyzer.exception.*; import com.resumeanalyzer.repository.UserRepository; import com.resumeanalyzer.security.JwtService; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.BadCredentialsException; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; @Transactional public AuthResponse register(AuthRequest request){String email=request.email().trim().toLowerCase();if(request.fullName()==null||request.fullName().isBlank())throw new BadRequestException("Full name is required for registration");if(users.existsByEmailIgnoreCase(email))throw new BadRequestException("An account already exists for this email");User user=users.save(User.builder().email(email).password(encoder.encode(request.password())).fullName(request.fullName().trim()).role(User.Role.ROLE_USER).build());return response(user);} @Transactional(readOnly=true) public AuthResponse login(AuthRequest request){User user=users.findByEmailIgnoreCase(request.email().trim()).orElseThrow(()->new BadCredentialsException("Invalid email or password"));if(!encoder.matches(request.password(),user.getPassword()))throw new BadCredentialsException("Invalid email or password");return response(user);} private AuthResponse response(User user){return new AuthResponse(jwt.generate(user),"Bearer",jwt.expirationSeconds(),user.getFullName(),user.getRole().name());} }
